jsxGraph.script:
board.suspendUpdate();
board.create('arrow', [[-6.5,0], [6.5,0]], {strokeColor: 'black', strokeWidth: 1});
board.create('arrow', [[0,-2.5], [0,2.5]], {strokeColor: 'black', strokeWidth: 1});
board.create('text', [6.3, -0.4, 'x'], {fontSize: 14});
board.create('text', [-0.4, 2.2, 'y'], {fontSize: 14});
board.create('functiongraph', [function(x){ return 4*x/(x*x+1); }, -6.5, 6.5], {strokeColor: '#4f46e5', strokeWidth: 2});
board.create('point', [1,2], {name: 'Max(1,2)', visible: true, size: 2, label: {autoPosition: false, offset: [0, 10]}});
board.create('point', [-1,-2], {name: 'Min(-1,-2)', visible: true, size: 2, label: {autoPosition: false, offset: [0, 10]}});
board.create('point', [0,0], {name: '(0,0)', visible: true, size: 2, label: {autoPosition: false, offset: [0, 10]}});
board.unsuspendUpdate();
